/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: true,

  images: {
    // /_next/image does nothing on Cloudflare Workers without an IMAGES
    // binding — it returns the original file, so next/image's srcset was a
    // list of identical URLs and every phone downloaded the 1600px
    // screenshot. This loader points at pre-sized files generated by
    // `npm run images` instead, so the browser picks a real size and no
    // image passes through the Worker at all.
    //
    // If Images is ever enabled on the account, delete these two lines and
    // uncomment the IMAGES binding in wrangler.jsonc; the variants become
    // redundant but harmless.
    loader: 'custom',
    loaderFile: './lib/image-loader.js',
  },

  // The generated share card is a real URL, so Google crawls and considers it
  // for indexing. It is an image of a page, not a page, and it was showing up
  // in Search Console as "crawled, currently not indexed". Keep it crawlable
  // — social scrapers must fetch it — but tell search engines not to index it.
  //
  // Static assets under /fonts are served by the Cloudflare assets layer
  // before the Worker runs, so they cannot be covered here. They need a
  // Cloudflare Transform Rule instead (see docs/seo.md).
  async headers() {
    return [
      {
        source: '/:path(opengraph-image|twitter-image)',
        headers: [{ key: 'X-Robots-Tag', value: 'noindex' }],
      },
    ];
  },
};

export default nextConfig;
